				}</style> <script>document.addEventListener("DOMContentLoaded", () => {
    const feedbackText = document.querySelector(".feedback-text");

    if (!feedbackText) {
        console.error("feedback-text element not found");
        return;
    }

    // Save the original text content
    const text = feedbackText.textContent.trim();
    feedbackText.textContent = ""; // Clear the text initially

    // Function to type out letters one by one
    const typeText = (index) => {
        if (index < text.length) {
            feedbackText.textContent += text[index]; // Add one letter at a time
            setTimeout(() => typeText(index + 1), 1); // Adjust speed here (100ms per letter)
        }
    };

    // Observer to start typing when the section is visible
    const observer = new IntersectionObserver(
        (entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    typeText(0); // Start animation
                    observer.disconnect(); // Stop observing after triggering
                }
            });
        },
        { threshold: 0.5 }
    );

    const feedbackSection = document.querySelector("#feedback");
    if (!feedbackSection) {
        console.error("#feedback section not found");
        return;
    }

    observer.observe(feedbackSection);
});</script><link rel="icon" href="/assets/wp-content/uploads/2025/01/cropped-detox-locator-logo2-32x32.png" sizes="32x32" /><link rel="icon" href="/assets/wp-content/uploads/2025/01/cropped-detox-locator-logo2-192x192.png" sizes="192x192" /><link rel="apple-touch-icon" href="/assets/wp-content/uploads/2025/01/cropped-detox-locator-logo2-180x180.png" /><meta name="msapplication-TileImage" content="/assets/wp-content/uploads/2025/01/cropped-detox-locator-logo2-270x270.png" /><style id="wp-custom-css">/* Parent Section */
#feedback {
    position: relative;
    padding: 50px 20px;
    background-color: #f9f9f9; /* Light background for visibility */
    overflow: hidden; /* Ensures no content spills outside */
}

/* Feedback Text Container */
.feedback-text-container {
    position: relative;
    width: 100%; /* Full width for the container */
    max-width: 800px; /* Restrict to a reasonable width */
    margin: 0 auto; /* Center it within the section */
    overflow: hidden; /* Critical to prevent text overflow */
    text-align: left; /* Align the text properly */
    padding: 20px; /* Optional: Add padding for spacing */
    background-color: #fff; /* Add background for visibility */
    border: 1px solid #ddd; /* Optional: Add border for style */
    border-radius: 8px; /* Optional: Rounded corners */
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1); /* Optional: Add shadow for aesthetics */
}

/* Feedback Text */
.feedback-text {
    font-family: Arial, sans-serif;
    font-size: 18px; /* Readable font size */
    line-height: 1.5; /* Proper line height for text */
    color: #333; /* Text color */
    white-space: pre-wrap; /* Preserve spaces and line breaks */
    overflow: hidden; /* Keep text confined to the container */
    word-wrap: break-word; /* Ensure long words break within the container */
    display: block; /* Ensures proper block behavior for text */
}
#input_1_16 {
  width: 100% !important;
}
.gform_heading {
  display: none;
}
.gfield_label {
  font-family: work sans !important;
  font-size: 16px !important;
}
#gform_submit_button_1 {
  background: #8AC20A;
  font-size: 16px;
  font-weight: 700;
  border-radius: 30px;
	transition:.3s;
}
